import{z as A,x as p,o as s,c as d,q as n,j as l,D as a,d as o,s as r,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"NFS 语义","description":"","frontmatter":{"title":"NFS 语义","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nfs-semantics.md","filePath":"cs/nfs-semantics.md","lastUpdated":1791063341000}'),B={name:"cs/nfs-semantics.md"};function c(S,e,C,m,f,F){const E=p("Mermaid");return s(),d("div",null,[e[2]||(e[2]=n('<h1 id="nfs-语义" tabindex="-1">NFS 语义 <a class="header-anchor" href="#nfs-语义" aria-label="Permalink to &quot;NFS 语义&quot;">​</a></h1><div class="epigraph"><p>NFS 把远程过程当成文件操作：客户端缓存使打开的文件不必每读一回服务器，于是 POSIX 单机语义被削弱成「关闭-打开」一类约定。</p><footer>—— 据 Sandberg et al., Design and Implementation of the Sun Network Filesystem；RFC 1813 / RFC 7530 对 NFSv3/v4 的整理</footer></div><p><a href="/cs/fuse">上一课</a>让操作出核。<a href="/cs/vfs">VFS</a> 底下也可以是网络。缺口不是套接字 API——主干已有——而是 <strong>NFS 相对本地 FS 少保证什么</strong>：缓存、删除仍打开的文件、锁、会话。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>本地 Unix：<code>write</code> 对其他进程立刻可见（同一页缓存）。NFS 客户端若缓存数据与属性，另一客户的写可能延迟可见。经典约定：close 后 open 看见最新（close-to-open）。NFSv4 用租约与委派加强，仍不是单机共享内存。缺口：文件句柄代替路径（服务器 inode 世代）；无状态 v3 vs 有状态 v4；<code>unlink</code> 仍打开时服务器 rename 到 <code>.nfs*</code> 隐藏名。本课不把 RPC 的 XDR 写成网络课。</p><p><span class="marginnote">属性缓存超时使 <code>stat</code> 便宜但不准。写缓存未刷时服务器崩溃，数据丢——应用仍要 fsync 语义的远程对应物。</span></p><p><span class="marginnote">术语翻译：close-to-open 就是用「close 时把改动刷回服务器、open 时重新取最新」的手段来做「给分布式缓存定一个最小一致点」的事——两次 open 之间，谁也不承诺你看见别的客户端的写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>lookup 向服务器要文件句柄。read：缓存命中则不发 RPC；失效则 GETATTR/READ。write：可异步，commit 才稳定。与 <a href="/cs/fsync">fsync</a>：客户端必须把脏页推到服务器并 COMMIT。对照 FUSE：两边都是「不是本地盘」，但 NFS 有共享多客户与网络分区。对照 overlay：层在本地；NFS 的 lower 若是远程，缓存叠缓存。</p><p><span class="marginnote">常见误区：初学者容易把 NFS 挂载当「慢一点的本地盘」。差别不在速度：本地 <code>write</code> 同机立即可见，NFS 另一客户端要等缓存约定；<code>stat</code> 可能报旧属性，锁语义也要单独确认——语义先于性能。</span></p>',10)),(s(),l(i,null,{default:a(()=>[r(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22read%2Fwrite%22%5D%20--%3E%20CC%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E7%BC%93%E5%AD%98%22%5D%0A%20%20CC%20--%3E%7C%22miss%20%E6%88%96%E5%A4%B1%E6%95%88%22%7C%20RPC%5B%22NFS%20RPC%22%5D%0A%20%20RPC%20--%3E%20SV%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E9%A1%B5%E7%BC%93%E5%AD%98%E4%B8%8E%E7%9B%98%22%5D%0A%20%20CLOSE%5B%22close-to-open%22%5D%20--%3E%20INV%5B%22%E5%B1%9E%E6%80%A7%2F%E6%95%B0%E6%8D%AE%E5%A4%B1%E6%95%88%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t("h2",{id:"机制",tabindex:"-1"},[o("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=t("p",null,"NFS 用「弱缓存一致性」换吞吐。这不是 bug，是课序要默认的前提：分布式文件不是本地 inode 的透明延伸。NFSv4 的 stateful 打开、委派（delegation）让服务器把缓存权交给某一客户，冲突时收回——更接近本地，仍有收回窗口。不要把本课写成限价簿的远程同步。",-1)),(s(),l(i,null,{default:a(()=>[r(E,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%20A%20%E5%86%99%E6%96%87%E4%BB%B6%22%5D%20--%3E%20AC%5B%22%E5%85%88%E8%90%BD%20A%20%E7%9A%84%E5%86%99%E7%BC%93%E5%AD%98%22%5D%0A%20%20AC%20--%3E%7C%22close%EF%BC%9A%E5%88%B7%E5%9B%9E%E6%9C%8D%E5%8A%A1%E5%99%A8%22%7C%20SV%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E4%B8%8A%E6%98%AF%E6%9C%80%E6%96%B0%E7%89%88%E6%9C%AC%22%5D%0A%20%20SV%20--%3E%20B1%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%20B%20%E6%AD%A4%E5%90%8E%20open%20%E2%87%92%20%E7%9C%8B%E5%88%B0%E6%96%B0%E6%95%B0%E6%8D%AE%22%5D%0A%20%20OLD%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%20B%20%E6%97%A9%E5%B7%B2%E6%89%93%E5%BC%80%E5%B9%B6%E6%8C%81%E6%9C%89%E8%AF%BB%E7%BC%93%E5%AD%98%22%5D%20--%3E%7C%22%E4%B8%8D%E9%87%8D%E6%96%B0%20open%22%7C%20STALE%5B%22%E4%BB%8D%E8%AF%BB%E5%88%B0%E6%97%A7%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=n('<p>这张图回答：close-to-open 到底保证什么。保证的只是「重新 open 一定看见 close 之前的写」；一直开着的 B 不受任何保护，读到旧数据不算违背语义，而是这条约定本来的边界。</p><p><span class="marginnote">直觉类比：v3 无状态像邮局不记你上次寄过什么——每个请求自带全部信息，崩溃后客户端重试即可；v4 有状态像图书馆借书登记——服务器记着谁借了什么，靠租约到期回收，登记簿本身也要恢复。</span></p><p>与 <a href="/cs/xattr-acl">ACL</a>：v4 ACL 可在线上走，与 POSIX 模式位映射有损。</p><p>实现上：NFSv4 委托让客户端缓存接近本地，但服务器收回时要收回冲突写。无状态 v3 把恢复推给客户端重试，打开文件在服务器崩溃后可能换文件句柄世代。 读法上只引用<a href="/cs/fuse">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 接口进阶」课序里，对象是 <strong>NFS 语义</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 pNFS 布局、RDMA NFS 的全部注册。不保证每个 NAS 设备实现委派。下一课在本地与远程都会出现的互斥：文件锁。</p><p>版本字段会变，课序钉的是机制对象「NFS 语义」，不是某一主线内核的结构体名。 后课默认：远程文件有缓存与 close-to-open 一类语义。字节范围锁与建议锁，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NFS 用句柄与客户端缓存；默认不是单机瞬时可见。</li><li>close-to-open 与 v4 委派是不同强度的补丁。</li><li>文件锁是下一课。</li><li>出处：Sandberg et al.；RFC 1813；RFC 7530；<em>OSTEP</em> 对 NFS 的讨论。</li></ul>',11))])}const u=A(B,[["render",c]]);export{h as __pageData,u as default};
